import{_ as a,c as s,o as t,b0 as o}from"./chunks/framework.CDI_EM33.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"nav/FaceBook/模板消息/消息模板指南.md","filePath":"nav/FaceBook/模板消息/消息模板指南.md","lastUpdated":1744007813000}'),r={name:"nav/FaceBook/模板消息/消息模板指南.md"};function l(p,e,n,c,i,h){return t(),s("div",null,e[0]||(e[0]=[o('<div class="info custom-block"><p class="custom-block-title">文档》WhatsApp Business 开放平台》消息》消息模板指南</p><p><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines" target="_blank" rel="noreferrer">消息模板指南</a></p></div><div class="warning custom-block"><p class="custom-block-title">警告</p><p>自 2025 年 4 月 1 日起，我们将暂停向拥有美国电话号码的 WhatsApp 用户发送营销模板消息。请参阅<a href="https://developers.facebook.com/docs/whatsapp/cloud-api/guides/send-message-templates#per-user-marketing-template-message-limits" target="_blank" rel="noreferrer">每个用户的营销模板消息限制</a>以了解更多信息。</p></div><h2 id="什么消息模板" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#--" target="_blank" rel="noreferrer">什么消息模板？</a> <a class="header-anchor" href="#什么消息模板" aria-label="Permalink to &quot;[什么消息模板？](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#--)&quot;">​</a></h2><p>模板用于通过模板消息来开启与客户之间的营销、交易相关和身份验证<a href="https://developers.facebook.com/docs/whatsapp/pricing#conversations" target="_blank" rel="noreferrer">对话</a>。与自由格式(普通)的消息不同，<code>对于到目前为止或在过去 24 小时内尚未给您发消息的客户，模板消息是唯一可向其发送的消息类型</code></p><p>模板必须经过批准，才能通过模板消息发送。此外，根据客户反馈和互动，系统还可以自动禁用模板。一个模板被禁用后，除非该模板的质量评分提高或该模板不再违反我们的 <a href="https://l.facebook.com/l.php?u=https%3A%2F%2Fwww.whatsapp.com%2Flegal%2Fbusiness-policy%2F&amp;h=AT3IeE3HUq_WaJ0m8HRMf6bt8R80C8Dw6iyuDwv5bVAnJXqwEjCVXl-YdinCn2AwLlwVLK0sq4YMQcAoeIHT5FiMP6GhX7VL9tPo38n3tSlWxojDWI_OrMjVA8y_Aua0e7JbOg" target="_blank" rel="noreferrer">WhatsApp Business</a> 政策或<a href="https://l.facebook.com/l.php?u=https%3A%2F%2Fwww.whatsapp.com%2Flegal%2Fcommerce-policy%2F&amp;h=AT1byK_SuhLk4IrfpbkJwhf8oDkttH9GnmPGQbQ4JY9ARM4aJG5r502SwGqOfs3Tt_aTw-GdvcP1bx_JJtss_My-nTs62pouw4mWkPKl2twb4n1YwyqHNOHn37924QJKBqBhWA" target="_blank" rel="noreferrer">商业</a>政策，否则您无法通过模板消息发送该模板。</p><h3 id="客户服务时间窗" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/cloud-api/guides/send-messages#-------" target="_blank" rel="noreferrer">客户服务时间窗</a> <a class="header-anchor" href="#客户服务时间窗" aria-label="Permalink to &quot;[客户服务时间窗](https://developers.facebook.com/docs/whatsapp/cloud-api/guides/send-messages#-------)&quot;">​</a></h3><p>无论 WhatsApp 用户何时向您发送消息，系统都会启动一个 24 小时计时器，称为“客户服务时间窗”。</p><p>在您与用户之间已开启一个客户服务时间窗时，您可以向该用户发送任何类型的消息；如果未开启客户服务时间窗，您只能向该用户发送模板消息，因为模板消息是可以在客户服务时间窗之外发送的唯一消息类型。</p><h2 id="模板创建" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---2" target="_blank" rel="noreferrer">模板创建</a> <a class="header-anchor" href="#模板创建" aria-label="Permalink to &quot;[模板创建](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---2)&quot;">​</a></h2><p>使用 Business 管理 API 创建模板。请参阅<a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates" target="_blank" rel="noreferrer">创建和管理模板</a>，了解创建模板的方法。或者，您可以<a href="https://www.facebook.com/business/help/2055875911147364" target="_blank" rel="noreferrer">使用 WhatsApp 管理工具手动创建模板</a></p><h3 id="创建模板名称内容限制" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#--" target="_blank" rel="noreferrer">创建模板名称内容限制</a> <a class="header-anchor" href="#创建模板名称内容限制" aria-label="Permalink to &quot;[创建模板名称内容限制](https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#--)&quot;">​</a></h3><div class="warning custom-block"><p class="custom-block-title">警告</p><ul><li>消息模板名称字段的限制为 512 个字符。</li><li>消息模板内容字段的限制为 1,024 个字符。</li><li>只有当模板处于<strong>已批准</strong>、<strong>未通过</strong>或<strong>已暂停</strong>状态时，才能对其进行编辑。您每天可以编辑模板一次，每个月最多可以编辑 10 次。</li><li>每个 WhatsApp Business 商业帐号每小时只能创建 100 个消息模板。</li><li>包含 4 个或以上按钮的模板或包含 1 个快速回复按钮和 1 个或多个其他类型按钮的模板无法在 WhatsApp 桌面版客户端上查看。如果 WhatsApp 用户收到一条包含此类模板的消息，系统会提示他们改用手机查看该消息。</li></ul></div><div class="warning custom-block"><p class="custom-block-title"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#create-and-manage-templates" target="_blank" rel="noreferrer">创建模板的数量限制</a></p><p>WhatsApp Business 帐户可以拥有的模板数量由其母公司决定。如果母公司未经验证，则其每个 WhatsApp Business 帐户最多可拥有 250 个模板。但是，如果母公司已经验证，并且其至少一个 WhatsApp Business 帐户拥有带有已批准显示名称的企业电话号码，则其每个 WhatsApp Business 帐户最多可以拥有 6,000 个模板。</p></div><h3 id="创建消息模板注意事项-💡" tabindex="-1"><a href="https://www.facebook.com/business/help/2055875911147364?id=2129163877102343" target="_blank" rel="noreferrer">创建消息模板注意事项 💡</a> <a class="header-anchor" href="#创建消息模板注意事项-💡" aria-label="Permalink to &quot;[创建消息模板注意事项 💡](https://www.facebook.com/business/help/2055875911147364?id=2129163877102343)&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">TIP</p><ul><li>消息模板名称:<code>只能包含小写字母数字字符和下划线 ( \\_ )。不允许包含其他字符或空格。</code></li><li>消息模板的组件:根据需要使用文本和/或媒体组件（包括参数占位符）填充模板。确保它不包含换行符、制表符或超过 4 个连续空格，并满足 Business Manager 或 WhatsApp Business Management API 中规定的长度限制。</li><li>您的企业所需的所有其他翻译。</li></ul></div><p>创建消息模板时，您可以点击“添加示例”按钮添加示例模板。这有助于我们在审核和批准过程中了解您计划发送哪种类型的消息。请确保这些是示例，并且不包含任何机密或个人信息</p><p>有关创建消息模板的更多详细步骤，请参阅<a href="https://www.facebook.com/business/help/2055875911147364?id=2129163877102343" target="_blank" rel="noreferrer">为您的 WhatsApp Business API 帐户创建消息模板。</a></p><h2 id="模板审核" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#----" target="_blank" rel="noreferrer">模板审核</a> <a class="header-anchor" href="#模板审核" aria-label="Permalink to &quot;[模板审核](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#----)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">警告</p><p>在创建模板后，可以提交模板以供审核。审核最多需要 24 小时。</p></div><p>我们作出决定后，WhatsApp 管理工具中将显示通知，并且我们将向商务管理平台管理员发送邮件。此外，如果您已订阅消息模板状态更改内容，我们还将发送 Webhooks 通知。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#monitoring-status-changes" target="_blank" rel="noreferrer">监控状态更改</a></p><div class="tip custom-block"><p class="custom-block-title"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#create-and-manage-templates" target="_blank" rel="noreferrer">模板官方是如何审核的？</a></p><p>Cloud API 使用机器学习来审查模板和变量参数，以保护 Cloud API 服务的安全性和完整性</p></div><p><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#template-review" target="_blank" rel="noreferrer">状态为 的模板 PENDING 正在接受模板审核。<code>我们会审核每个新创建或编辑的模板的内容，以确保其符合我们的内容准则和政策。</code>根据审核结果，我们会自动将其状态更改为 APPROVED 或 REJECTED，从而触发消息模板状态更新 webhook</a></p><div class="warning custom-block"><p class="custom-block-title">警告</p><p>如果消息模板已获批准，其状态将被设置为启用 - 质量待定，您可以开始向客户发送此模板。</p></div><p>如果消息模板未通过审核，您可以<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#editing" target="_blank" rel="noreferrer">编辑模板</a>，并重新提交以供审核，也可以对此决定提出<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#appeals" target="_blank" rel="noreferrer">申诉</a>。</p><h2 id="编辑模板" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---4" target="_blank" rel="noreferrer">编辑模板</a> <a class="header-anchor" href="#编辑模板" aria-label="Permalink to &quot;[编辑模板](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---4)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">警告</p><ul><li><p>如果您已经创建消息模板，且其状态为“已被拒”，您可以对其进行编辑,【<code>已经审核通过的模板无法进行编辑-对外描述。</code>】<a href="https://www.facebook.com/business/help/287011426725347" target="_blank" rel="noreferrer">详情查看官方文档</a></p></li><li><p>只有当模板处于<strong>已批准</strong>、<strong>未通过</strong>或<strong>已暂停</strong>状态时，才能对其进行编辑。您每天可以编辑模板一次，每个月最多可以编辑 10 次。<a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#--" target="_blank" rel="noreferrer">详情查看官方文档</a></p></li></ul></div><div class="warning custom-block"><p class="custom-block-title"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates" target="_blank" rel="noreferrer">限制</a></p><ul><li>仅可编辑状态为<code>已批准</code>、<code>已拒绝</code>或 的模板。<code>暂停</code></li><li>您只能编辑模板的<code>模板类别</code>或组<code>成模板的组件对象数组</code></li><li>您不能编辑<code>模板类别</code>已批准的模板。</li><li>已批准的模板在 30 天内最多可编辑 10 次，在 24 小时内最多可编辑 1 次。已拒绝或暂停的模板可无限次编辑。</li><li>编辑已批准或暂停的模板后，除非模板审核失败，否则它将自动获得批准。</li></ul></div><p>您可以使用 <a href="https://www.facebook.com/business/help/287011426725347" target="_blank" rel="noreferrer">WhatsApp 管理工具</a>或<a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#edit-a-message-template" target="_blank" rel="noreferrer">消息模板</a>端点编辑模板。 <span style="color:#FF0000;"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---4" target="_blank" rel="noreferrer">请注意!</a></span>，如果编辑消息模板并重新提交以供审核，该模板状态将设置为<strong>审核中</strong>，在状态设置为<strong>启用</strong>之前，您不能将该模板发送给客户。</p><h2 id="未通过审核的常见原因" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#----------" target="_blank" rel="noreferrer">未通过审核的常见原因</a> <a class="header-anchor" href="#未通过审核的常见原因" aria-label="Permalink to &quot;[未通过审核的常见原因](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#----------)&quot;">​</a></h2><p>通常情况下，提交材料未通过审核的原因如下，请确保自己避免这些错误。</p><ul><li>变量参数缺失或所用的大括号不匹配。正确格式为 <code>1</code>。</li><li>变量参数包含特殊字符，例如 <code>#</code>、<code>$</code> 或 <code>%</code>。</li><li>变量参数不连续。例如，定义了 <code>1</code>、<code>2</code>、<code>4</code>、<code>5</code>，但没有 <code>3</code>。</li><li>相对于消息长度而言，模板包含太多变量参数。您需要减少可变参数的数量或增加消息长度。</li><li>消息模板不能以参数结束。</li><li><code>消息模板包含的内容违反 WhatsApp 的商业政策</code>：您出售商品或服务时，我们会将所有与该等商品或服务相关的消息或媒体（包括任何描述、价格、费用、税费和/或任何法律规定的披露内容）视为交易的一部分。所有交易都必须遵循 <a href="https://www.whatsapp.com/legal/commerce-policy/" target="_blank" rel="noreferrer">WhatsApp 商业政策</a>。</li><li><code>消息模板包含的内容违反</code> <a href="https://l.facebook.com/l.php?u=https%3A%2F%2Fwww.whatsapp.com%2Flegal%2Fbusiness-policy%2F&amp;h=AT3ixfpN46b4qw4_WjXqSwAW2CkfSGPkVtepAtd9xp2dawcAq0sDOn7Ps1v3BPSqMTynZKKjOq1KHsm-IVGKeYALEXFGFXp9nZCDLyJBokalN-sqwzma1D5pFYjU7sisLtxRHA" target="_blank" rel="noreferrer">WhatsApps Business 政策</a>：请勿请求用户提供敏感身份识别信息。例如，请勿要求用户分享完整的个人支付卡号码、财务账号、国民身份证号码或其他敏感身份识别信息。此外，也请勿向用户请求可能包含敏感身份识别信息的文件。可以请求部分身份识别信息（例如：社会安全号码的最后 4 位数）。</li><li>内容包含辱骂性或威胁性内容，例如以法律诉讼威胁客户，或威胁要公开羞辱客户。</li><li><code>该消息模板与某个现有模板重复了</code>。如果所提交模板正文和页脚中的措辞与现有模板的相关内容一样，重复的模板将无法通过审核。</li></ul><p><a href="https://business.facebook.com/business-support-home" target="_blank" rel="noreferrer">业务支持中心</a>中将显示模板被拒通知，并注明被拒的原因。前往<strong>业务支持中心</strong>的<strong>账户概览</strong> &gt; <strong>查看我的账户</strong>（按钮）&gt;（您的 Meta 业务账户）&gt;（您的 WABA）&gt; <strong>被拒的消息模板</strong>，可查看被拒详情。被拒信息也会通过邮件发送给您。</p><p>您可以查阅<strong>业务支持中心</strong>通知，查看与被拒的重复模板具有相同内容的现有模板的名称和语言。您也可以选择编辑模板并重新提交。</p><p>这项检查不适用于归类为 <code>AUTHENTICATION(身份验证)</code> 的模板。</p><h2 id="模板被拒原因" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/business-management-api/webhooks/components#value-object" target="_blank" rel="noreferrer">模板被拒原因</a> <a class="header-anchor" href="#模板被拒原因" aria-label="Permalink to &quot;[模板被拒原因](https://developers.facebook.com/docs/whatsapp/business-management-api/webhooks/components#value-object)&quot;">​</a></h2><ul><li>ABUSIVE_CONTENT — 经判定，内容违规。</li><li>INCORRECT_CATEGORY — 经判定，类别有误。请参阅<a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#template-categories" target="_blank" rel="noreferrer"><code>模板类别</code></a>。</li><li>INVALID_FORMAT — 内容重复或<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#samples" target="_blank" rel="noreferrer"><code>示例</code></a>缺失。</li><li>NONE — 模板获批时设置的默认值。</li><li>SCAM — 经判定，内容为诈骗。</li></ul><h2 id="模板状态" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---5" target="_blank" rel="noreferrer">模板状态</a> <a class="header-anchor" href="#模板状态" aria-label="Permalink to &quot;[模板状态](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---5)&quot;">​</a></h2><p>根据类别验证和模板审核的结果，我们会将模板的 <code>status</code>(状态) 设置或更改为以下值之一：</p><ul><li><code>APPROVED</code> — 模板已通过模板审核并获得批准，现在可<a href="https://developers.facebook.com/docs/whatsapp/business-management-api/message-templates#sending-templates" target="_blank" rel="noreferrer">通过模板消息发送</a>。</li><li><code>PENDING</code> — 模板已通过类别验证，将进入模板审核流程。</li><li><code>REJECTED</code> — 模板未通过类别验证或模板审核。</li></ul><p>请参阅 <a href="https://developers.facebook.com/docs/graph-api/reference/whats-app-business-hsm/#fields" target="_blank" rel="noreferrer">WhatsApp 消息模板</a>端点参考文档，了解所有可能的字段和状态。</p><p>模板具有以下状态。</p><ul><li><strong>审核中</strong>：表示模板仍在审核中。<code>审核最多需要 24 小时</code></li><li><strong>未通过</strong>：模板在审核过程中未通过审核，或违反我们的一项或多项政策。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#appeals" target="_blank" rel="noreferrer">申诉</a>。</li><li><strong>启用 - 质量待定</strong>：尚未收到客户对消息模板的质量反馈或读取率信息。您可以将此状态的消息模板发送给客户。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#quality-rating" target="_blank" rel="noreferrer">质量评分</a>。</li><li><strong>启用 - 高质量</strong>：几乎未收到或未收到客户对模板的负面反馈。您可以将此状态的消息模板发送给客户。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#quality-rating" target="_blank" rel="noreferrer">质量评分</a>。</li><li><strong>启用 - 中等质量</strong>：已收到多位客户对模板的负面反馈或低读取率信息，模板状态可能会很快变为暂停或禁用。您可以将此状态的消息模板发送给客户。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#quality-rating" target="_blank" rel="noreferrer">质量评分</a>。</li><li><strong>启用 - 低质量</strong>：已收到多位客户对模板的负面反馈或低读取率信息。您可以将此状态的消息模板发送给客户，但此模板面临很快被暂停或禁用的危险，因此建议您尽快解决客户举报的问题。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#quality-rating" target="_blank" rel="noreferrer">质量评分</a>。</li><li><strong>暂停</strong>：模板因客户的负面反馈或低读取率被暂停使用。您不能将此状态的消息模板发送给客户。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#template-pausing" target="_blank" rel="noreferrer">模板暂停</a>。</li><li><strong>禁用</strong>：模板因客户的负面反馈被禁用。您不能将此状态的消息模板发送给客户。</li><li><strong>请求申诉</strong>：表示已请求申诉。请参阅<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#appeals" target="_blank" rel="noreferrer">申诉</a>。</li></ul><h2 id="发送模板" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---5" target="_blank" rel="noreferrer">发送模板</a> <a class="header-anchor" href="#发送模板" aria-label="Permalink to &quot;[发送模板](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---5)&quot;">​</a></h2><p>模板获得批准后（模板的 <code>状态</code> 设为 <code>ACTIVE（有效）</code>），您即可开始向客户发送此模板</p><p>请注意，系统可根据客户反馈和互动率，将消息模板的 <code>status(状态)</code> 从 <code>ACTIVE(有效）</code> 自动更改为 <code>PAUSED（暂停）</code> 或 <code>DISABLED（禁用）</code>。因此，建议您<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#monitoring-status-changes" target="_blank" rel="noreferrer">监控状态更改</a>，在所依赖的消息模板变为暂停或禁用状态，或者面临这种危险时，采取适当的措施。</p><h2 id="模板调控" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----3" target="_blank" rel="noreferrer">模板调控</a> <a class="header-anchor" href="#模板调控" aria-label="Permalink to &quot;[模板调控](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----3)&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">警告</p><p>从 2024 年 4 月 30 日开始，模板调控适用于营销和交易相关两类模板。</p></div><p>模板调控是一种机制，为客户留出时间来对模板提供早期反馈。模板调控会识别并暂停收到负面反馈的模板或互动量欠佳的模板，在您将这些模板发送给太多客户之前，给您足够的时间来调整其内容，从而降低产生负面反馈的可能性，避免对您的企业造成影响。</p><p>模板受到调控时，系统将正常发送消息，直到达到未指定的阈值。一旦消息数量达到此阈值，系统将暂停发送使用此模板的后续消息，以便留足时间等待客户反馈。我们收到表示质量良好的信号后，会向整个目标受众群体大量发送使用该模板的后续消息。如果收到表示质量欠佳的信号，我们会中断发送使用该模板的后续消息，以便给您机会对内容、定位等作出调整。</p><p>如果是正面反馈，且模板的质量评分更改为<strong>高质量</strong>，系统将放行并正常发送之前暂停发送的消息。 如果是负面反馈，且模板质量更改为<strong>低质量</strong></p><h2 id="监控状态更" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#------" target="_blank" rel="noreferrer">监控状态更</a> <a class="header-anchor" href="#监控状态更" aria-label="Permalink to &quot;[监控状态更](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#------)&quot;">​</a></h2><p>模板的状态可根据审核决定、申诉结果或<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#quality-rating" target="_blank" rel="noreferrer">质量评分</a>更改自动更改。</p><p>如果消息模板的质量下降,可前往 <strong>WhatsApp 管理工具</strong> &gt; <strong>消息模板</strong>，然后将鼠标指针悬停在相关消息模板上。界面上应出现提示信息，在其中显示有关问题实质的信息。根据此信息，您可能希望<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#editing" target="_blank" rel="noreferrer">编辑模板</a>并提交以供重新审核，使用不同的模板，或更改应用的业务逻辑。如果您已编辑消息模板且模板重新获得批准，则只要将其发送给客户后未时常收到负面反馈或低读取率信息，其质量评分就会逐渐提高。</p><h2 id="质量评分" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----4" target="_blank" rel="noreferrer">质量评分</a> <a class="header-anchor" href="#质量评分" aria-label="Permalink to &quot;[质量评分](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----4)&quot;">​</a></h2><p>每个消息模板的质量评分都取决于使用情况、客户反馈和互动。当消息模板的状态为<strong>启用</strong>时，其评分将显示在 WhatsApp 管理工具中，并且将显示在消息模板状态中的连字符之后：</p><ul><li>启用 - <strong>质量待定</strong>（以绿色突出显示）</li><li>启用 - <strong>高质量</strong>（以绿色突出显示）</li><li>启用 - <strong>中等质量</strong>（以黄色突出显示）</li><li>启用 - <strong>低质量</strong>（以红色突出显示）</li></ul><p>获得批准的消息模板的初始评分是<strong>质量待定</strong></p><ul><li>如果持续收到特定消息模板的负面反馈或低互动率信息，此模板的状态最终将发生更改。只要消息模板的状态为<strong>启用</strong>，不管质量评分如何，您都可以将其发送给客户</li><li>在消息模板的状态更改为任何其他状态后，如果状态未重新变为“启用”，您就不能将此模板发送给客户。请参阅<a href="https://developers.facebook.com/docs/whatsapp/business-management-api/webhooks/components#message-template-quality-update" target="_blank" rel="noreferrer">消息模板质量更新</a></li></ul><h2 id="模板暂停" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----5" target="_blank" rel="noreferrer">模板暂停</a> <a class="header-anchor" href="#模板暂停" aria-label="Permalink to &quot;[模板暂停](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----5)&quot;">​</a></h2><p>如果某消息模板处于最低质量评分（状态为<strong>启用 - 低质量</strong>），则系统会自动暂停此模板一段时间，以保护使用此模板的电话号码的质量评分。暂停时长如下：</p><ul><li>第 1 个实例：<strong>暂停</strong> 3 小时</li><li>第 2 个实例：<strong>暂停</strong> 6 小时</li><li>第 3 个实例：<strong>禁用</strong></li></ul><p><code>暂停特定消息模板（状态为 暂停）后，不能将其发送给客户，因此应暂停依赖此模板的所有自动发消息的营销活动</code></p><p>暂停最初不会影响发送消息模板所使用的公司电话号码，也不会导致电话号码的发消息上限受到缩减。其他高质量的消息模板可继续使用此电话号码进行发送。但是，如果公司持续发送<strong>低质量</strong>状态的消息模板，此电话号码最终可能会受到影响。</p><h2 id="取消暂停" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----5" target="_blank" rel="noreferrer">取消暂停</a> <a class="header-anchor" href="#取消暂停" aria-label="Permalink to &quot;[取消暂停](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#-----5)&quot;">​</a></h2><p>在达到上述暂停时长要求后，模板会自行取消暂停。取消暂停后，模板的状态将设置为<strong>启用</strong>，您又可以开始向客户发送此模板了。</p><p>模板的质量评分也会根据收到的客户最近对模板的反馈重置为特定值。</p><h2 id="模板申诉" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---6" target="_blank" rel="noreferrer">模板申诉</a> <a class="header-anchor" href="#模板申诉" aria-label="Permalink to &quot;[模板申诉](https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#---6)&quot;">​</a></h2><p>如果提交材料未通过审核，您可以提出申诉。请注意，申诉时必须<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#samples" target="_blank" rel="noreferrer">加入示例</a>。如果已获批准的模板变为禁用状态，您还可以<a href="https://developers.facebook.com/docs/whatsapp/message-templates/guidelines#editing" target="_blank" rel="noreferrer">编辑</a>模板并重新提交以供审核。</p><p>在 <strong>WhatsApp 管理工具</strong>中：</p><ol><li>将鼠标指针悬停在行李箱图标（<strong>账户工具</strong>）上，然后点击<strong>消息模板</strong>。</li><li>如果您有多个 WhatsApp Business 商业帐号，可使用右上角的下拉菜单选择要管理模板的帐号。</li><li>找到要编辑的消息模板，并点击此模板。</li><li>编辑模板的内容。</li><li>点击<strong>添加示例</strong>按钮，然后添加变量值和图片示例。</li><li>点击<strong>提交</strong>。</li></ol><p>我们将审核申诉，并在 24 小时内作出决定。</p><h2 id="政策执行" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/overview/policy-enforcement" target="_blank" rel="noreferrer">政策执行</a> <a class="header-anchor" href="#政策执行" aria-label="Permalink to &quot;[政策执行](https://developers.facebook.com/docs/whatsapp/overview/policy-enforcement)&quot;">​</a></h2><p>为确保持续在 WhatsApp Business 开放平台上提供高质量对话服务，我们将开始对屡次违反 <a href="https://www.whatsapp.com/legal/business-policy/" target="_blank" rel="noreferrer">WhatsApp Business 消息政策</a>、<a href="https://www.whatsapp.com/legal/commerce-policy/?fbclid=IwAR2vx5t1ncfK-mOnEu62wdvdgZc7rOTaUrX74EtwYCosTRJ2Sqyhr2bIPSM" target="_blank" rel="noreferrer">WhatsApp 商业政策</a>或 <a href="https://l.facebook.com/l.php?u=https%3A%2F%2Fwww.whatsapp.com%2Flegal%2Fbusiness-terms&amp;h=AT2guiJNZjrVcdGq1atz3jvPhkWstwOBHjfdFjvHFqDogsa9ckTrZzlytPBgESuss4NmG4eGU2Sh_p7Dr-rNVD12GqsJyuRSzrh3OtI0OMVconuXTk1RElp7xYnIfdUu1iI_ig" target="_blank" rel="noreferrer">WhatsApp Business 服务条款</a>的 WhatsApp Business 商业帐号采取强制措施。</p><h3 id="政策执行措施" tabindex="-1">政策执行措施 <a class="header-anchor" href="#政策执行措施" aria-label="Permalink to &quot;政策执行措施&quot;">​</a></h3><p><code>根据问题的数量和严重程度，帐号可能会受到限制或禁用。</code>可以在<a href="https://developers.facebook.com/docs/whatsapp/overview/policy-enforcement#business-support-home" target="_blank" rel="noreferrer">业务支持中心</a>中查看具体限制以及有关后续步骤的信息，同时请求对具体政策问题进行复审。</p><p>受限或禁用帐号仍可以对问题提出上诉或予以承认。如果申诉或承认后，开放平台撤销问题，该帐号将恢复到之前的状态。</p><h2 id="违反-whatsapp-business-开放平台政策的行为" tabindex="-1"><a href="https://developers.facebook.com/docs/whatsapp/overview/policy-enforcement/violations" target="_blank" rel="noreferrer">违反 WhatsApp Business 开放平台政策的行为</a> <a class="header-anchor" href="#违反-whatsapp-business-开放平台政策的行为" aria-label="Permalink to &quot;[违反 WhatsApp Business 开放平台政策的行为](https://developers.facebook.com/docs/whatsapp/overview/policy-enforcement/violations)&quot;">​</a></h2><p>在 WhatsApp Business 开放平台上执行商业交易政策和 Business 政策。请阅读这份<a href="https://developers.facebook.com/docs/whatsapp/overview/policy-enforcement" target="_blank" rel="noreferrer">指南</a>，简要了解该政策执行系统的运作方式和产品体验。</p><p>以下列表列出了会导致商家被认定为违反政策的行为</p>',79)]))}const g=a(r,[["render",l]]);export{m as __pageData,g as default};
